def _format_location(parsed: Tuple[str, int, int, int]) -> str:
    zone, aisle, shelf, level = parsed
    return f"{zone}-{aisle:02d}-{shelf:02d}-{level}"


def cycle_count_variance(lines: Iterable[str], case_sizes: Mapping[str, int], counts: Mapping[Tuple[str, str], int]) -> List[Tuple[str, str, int]]:
    system_stock = on_hand_by_location(lines, case_sizes)
    normalized_counts: Dict[Tuple[str, str], int] = defaultdict(int)
    counted_locations: set = set()
    for (raw_sku, raw_location), qty in counts.items():
        if qty < 0:
            raise ValueError(f"Counted quantity cannot be negative: {qty}")
        canonical_sku = normalize_sku(raw_sku)
        parsed_loc = parse_location(raw_location)
        canonical_location = _format_location(parsed_loc)
        key = (canonical_sku, canonical_location)
        normalized_counts[key] += qty
        counted_locations.add(canonical_location)
    results: List[Tuple[str, str, int]] = []
    stock_by_location: Dict[str, Dict[str, int]] = defaultdict(dict)
    for (sku, loc), qty in system_stock.items():
        stock_by_location[loc][sku] = qty
    for loc in counted_locations:
        skus_in_loc = stock_by_location.get(loc, {})
        counted_skus_in_loc = {sku for (sku, l), _ in normalized_counts.items() if l == loc}
        all_skus = set(skus_in_loc.keys()) | counted_skus_in_loc
        for sku in all_skus:
            sys_qty = skus_in_loc.get(sku, 0)
            cnt_qty = normalized_counts.get((sku, loc), 0)
            variance = cnt_qty - sys_qty
            if variance != 0:
                results.append((sku, loc, variance))
    results.sort(key=lambda x: (x[1], x[0]))
    return results
