        if sku in sku_weights and sku_weights[sku] != unit_weight:
            raise ValueError(f"SKU {sku} has inconsistent unit weights: {sku_weights[sku]} and {unit_weight}")
        sku_weights[sku] = unit_weight
        sku_qty[sku] += qty
    items: List[Tuple[str, int]] = []
    for sku, total_qty in sku_qty.items():
        unit_weight = sku_weights[sku]
        for _ in range(total_qty):
            items.append((sku, unit_weight))
    bins = first_fit_decreasing(items, max_parcel_grams)
    result: List[Dict[str, int]] = []
    for bin_items in bins:
        parcel: Dict[str, int] = defaultdict(int)
        for sku, _weight in bin_items:
            parcel[sku] += 1
        result.append(dict(parcel))
    return result"}}

